/// Registry entry for `process.expander`.
pub static EXPANDER_SPEC: ModelSpec = ModelSpec {
    id: "process.expander",
    kind: "direct",
    algorithm: None,
    checks: EXPANDER_CHECKS,
    cases: EXPANDER_CASES,
};

static FAULT_TREE_CHECKS: &[SpecCheck] = &[SpecCheck {
    on_input: true,
    check: RangeCheck {
        quantity: "max_cardinality",
        min: Some(1.0),
        min_inclusive: true,
        max: None,
        max_inclusive: true,
        equals: None,
        band: Band::Outside,
        severity: Severity::Error,
        code: WarningCode::OutOfValidRange,
        rationale: "the class's mask loop starts at one and can never return the empty cut set",
    },
}];

