/// Registry entry for `process.filter`.
pub static FILTER_SPEC: ModelSpec = ModelSpec {
    id: "process.filter",
    kind: "direct",
    algorithm: None,
    checks: FILTER_CHECKS,
    cases: FILTER_CASES,
};

static FIRE_CASE_RELIEF_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "wetted_area",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a negative area is not a wetted area; the class silently falls back",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "vessel_diameter",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a negative diameter is not a diameter; the class silently falls back",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "wetted_height",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a negative height is not a height; the class silently falls back",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "latent_heat",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a negative latent heat is not a latent heat; the class silently defaults it",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "relieving_temperature",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a non-positive absolute temperature is not a relieving state",
        },
    },
];

