static GAS_DISPERSION_ALGORITHM: ModelAlgorithm = ModelAlgorithm {
    scheme: "pasquill_gifford_or_britter_mcquaid_screening",
    convergence: "absolute",
    tolerance: 0.5,
    max_iterations: 60,
    bracket: None,
    initialisation: Some("ambient_tp_flash"),
    initial_temperature: None,
    inner: None,
    fallback: None,
};

/// Registry entry for `process.gas_dispersion`.
pub static GAS_DISPERSION_SPEC: ModelSpec = ModelSpec {
    id: "process.gas_dispersion",
    kind: "procedure",
    algorithm: Some(&GAS_DISPERSION_ALGORITHM),
    checks: GAS_DISPERSION_CHECKS,
    cases: GAS_DISPERSION_CASES,
};

static GAS_SCRUBBER_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "pressure_drop",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a vessel passes pressure down, not up",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "internal_diameter",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a diameter is a positive length, and the cross-section divides by nothing but its own square - NeqSim's `getSepCrossArea` returns a zero area and its `getCapacityUtilization` then answers NaN, which this refuses at the input instead",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "design_gas_load_factor",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a Souders-Brown load factor is a positive velocity; zero is a vessel that admits no gas at all",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "gas_in_liquid",
            min: Some(0.0),
            min_inclusive: true,
            max: Some(1.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "an entrainment fraction is a fraction",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "volume_safety_factor",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a flow multiplier; zero sizes nothing",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "design_liquid_level_fraction",
            min: Some(0.0),
            min_inclusive: true,
            max: Some(1.0),
            max_inclusive: false,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a fraction of the cross-section; at one there is no gas area",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "max_operation_pressure",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a pressure the wall thickness divides by",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "allowable_stress",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the ASME denominator subtracts the pressure from twice it",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "joint_efficiency",
            min: Some(0.0),
            min_inclusive: false,
            max: Some(1.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a weld joint efficiency is at most one",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "corrosion_allowance",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "an allowance adds metal; a negative one removes it",
        },
    },
];

