/// Registry entry for `process.heat_exchanger`.
pub static HEAT_EXCHANGER_SPEC: ModelSpec = ModelSpec {
    id: "process.heat_exchanger",
    kind: "direct",
    algorithm: None,
    checks: HEAT_EXCHANGER_CHECKS,
    cases: HEAT_EXCHANGER_CASES,
};

