static RATE_BASED_PACKED_COLUMN_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "column_diameter",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "every velocity and the segment volume divide by the cross-section",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "packed_height",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "**the class allows zero and forbids only a negative height**, which is what makes the zero-height state valid",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "number_of_segments",
            min: Some(1.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a column of no segments has no profile",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "max_iterations",
            min: Some(1.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the loop runs at least once, and a cap of zero has no last iterate to publish",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "convergence_tolerance",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a convergence gate is positive, and zero is a solve that never stops",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "gas_n",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "the interface mixture sums the two inlets' moles",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "liquid_n",
            min: Some(0.0),
            min_inclusive: false,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "likewise",
        },
    },
];

