pub static SPLITTER_SPEC: ModelSpec = ModelSpec {
    id: "process.splitter",
    kind: "direct",
    algorithm: None,
    checks: SPLITTER_CHECKS,
    cases: SPLITTER_CASES,
};

static STIRRED_TANK_REACTOR_CHECKS: &[SpecCheck] = &[
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "conversion",
            min: Some(0.0),
            min_inclusive: true,
            max: Some(1.0),
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a conversion is a fraction of the limiting reactant",
        },
    },
    SpecCheck {
        on_input: true,
        check: RangeCheck {
            quantity: "pressure_drop",
            min: Some(0.0),
            min_inclusive: true,
            max: None,
            max_inclusive: true,
            equals: None,
            band: Band::Outside,
            severity: Severity::Error,
            code: WarningCode::OutOfValidRange,
            rationale: "a vessel passes pressure down, not up",
        },
    },
];

